<?php
$pageTitle='Tournament Results';require_once __DIR__.'/includes/header.php';$t=active_tournament($pdo);
$champion=null;$runner=null;$matches=[];$semifinalists=[];
if($t){$s=$pdo->prepare("SELECT m.*,p1.name p1_name,p2.name p2_name,w.name winner_name FROM matches m LEFT JOIN participants p1 ON p1.id=m.participant1_id LEFT JOIN participants p2 ON p2.id=m.participant2_id LEFT JOIN participants w ON w.id=m.winner_id WHERE m.tournament_id=? AND m.status='finished' ORDER BY m.round_number DESC,m.match_number");$s->execute([$t['id']]);$matches=$s->fetchAll();foreach($matches as $row){if($row['round']==='Semi Final')$semifinalists[]=(int)$row['participant1_id']===(int)$row['winner_id']?$row['p2_name']:$row['p1_name'];}if($t['champion_id']){$c=$pdo->prepare('SELECT * FROM participants WHERE id=?');$c->execute([$t['champion_id']]);$champion=$c->fetch();$final=$matches[0]??null;if($final){$runnerId=(int)$final['participant1_id']===(int)$final['winner_id']?$final['participant2_id']:$final['participant1_id'];$c->execute([$runnerId]);$runner=$c->fetch();}}}
?>
<main><?php if($champion):?><section class="champion"><div class="container"><div class="trophy"><i class="fa-solid fa-trophy"></i></div><div class="eyebrow">Tournament champion</div><h1><?=e($champion['name'])?></h1><h2><?=e($t['name'])?></h2><?php if($runner):?><p>Runner Up · <?=e($runner['name'])?></p><?php endif;?><?php if($semifinalists):?><p>Semi Finalists · <?=e(implode(' & ',array_filter($semifinalists)))?></p><?php endif;?></div></section><?php else:?><section class="page-hero"><div class="container"><div class="eyebrow">Official outcomes</div><h1>Latest results</h1><p>The champion will appear here when the Final is completed.</p></div></section><?php endif;?><section class="section"><div class="container"><div class="section-head"><div><div class="eyebrow">Completed matches</div><h2>Results archive</h2></div></div><div class="grid grid-3"><?php if(!$matches):?><div class="card empty"><i class="fa-solid fa-flag-checkered"></i><p>No completed matches yet.</p></div><?php endif;foreach($matches as $m):?><a class="card match-card" href="match.php?id=<?=$m['id']?>"><div class="match-card-head"><span class="round-label"><?=e($m['round'])?></span><span class="badge finished">Finished</span></div><div class="team-line"><span><?=e($m['p1_name'])?></span><strong class="score"><?=$m['score1']?></strong></div><div class="team-line"><span><?=e($m['p2_name'])?></span><strong class="score"><?=$m['score2']?></strong></div><div class="match-card-foot"><span>Winner</span><strong><?=e($m['winner_name'])?></strong></div></a><?php endforeach;?></div></div></section></main>
<?php require __DIR__.'/includes/footer.php';?>
